def validate_hr788_boundaries(action):
    meaning=action['meaning'];require('may use reimbursable agreements' in meaning and 'must ensure inclusion' in meaning and 'as appropriate' in meaning and 'two years after enactment' in meaning,'788duties/permissions/qualification/report clock differ');require('Section3 authorizes no additional amounts to be appropriated' in meaning and 'neither makes an appropriation' in meaning and 'existing funding' in meaning,'788no-additional-authorization boundary differs');require('does not replace that framework' in meaning and 'nondiscrimination' in meaning and 'not a current consolidated implementation' in meaning,'788incorporated security scope/safeguards differ')

def validate_hr758_boundaries(action):
    meaning=action['meaning'];require('must provide alternative-deadline procedures' in meaning and 'serious crash injury' in meaning and 'separately require injury or death' in meaning and 'disabling-damage/tow-only' in meaning,'758report trigger/injury accommodation differs');require('INTERNAL digital database' in meaning and 'PUBLIC annual report' in meaning and 'does not personally identify any employee, contractor or other individual' in meaning and 'which penalty, if any' in meaning,'758internal/public privacy or discretionary penalty boundary differs')

def validate_hr993_boundaries(action):
    meaning=action['meaning'];require('AUTHORIZED to maintain' in meaning and 'does not require creation of a team' in meaning and 'MUST require operating procedures' in meaning and 'does not require deployment of every example' in meaning,'993team permission/conditional duty/technology example scope differs');require('including NEGATIVE consequences' in meaning and 'privacy and security impacts on border communities' in meaning and 'AND ANNUALLY THEREAFTER' in meaning and 'distinct from the one-time180day plan' in meaning,'993negative consequences/privacy/report clocks differ')

def validate_hr359_boundaries(action,baseline):
    meaning=action['meaning'];require('AT LEAST QUARTERLY THEREAFTER' in meaning and 'MAKE IT PUBLICLY AVAILABLE' in meaning and 'within120days after enactment' in meaning and 'Senate Energy/Natural Resources and Appropriations committees' in meaning,'359public/quarterly/deadline/recipient boundary differs');require('may REDUCE OR ELIMINATE applied-R&D' in meaning and 'authority to REDUCE the non-Federal share' in meaning and 'TWO-YEAR period beginningAugust9,2022' in meaning and 'rather than a new waiver power' in meaning,'359distinct waiver powers/dated exemption differs');require(all(x in baseline['text'] for x in ['not less than 20 percent','not less than 50 percent','basic or fundamental nature','2-year period beginning on August 9, 2022','a fee charged for the use of a Department facility','small business technology transfer program']),'359material baseline defaults/exclusions/dated exemption lost')

def validate_hr1263_boundaries(action):
    meaning=action['meaning'];require('SEEK NEGOTIATIONS' in meaning and 'ONLY IF the governments enter that written agreement' in meaning and 'not new project financing' in meaning and 'SUBJECT TO ETHICS REVIEW AND APPROVAL' in meaning,'1263negotiation/conditional group/financing/ethics boundary differs');require('UNACCEPTED candidate proposal' in meaning and 'competing boundary interpretation requiring independent review' in meaning,'1263candidate taxonomy became accepted membership')

def validate_hr1263_nondirectional(readable):
    member=next(m for m in readable['members'] if m['member_id']=='M001184');require(all('house:119:1:132' not in f['action_ids'] for f in member['findings']),'1263Not Voting became directional finding')

def validate_hr4016_amend114_boundaries(action,target):
    meaning=action['meaning'];require('one $500 million allocation' in meaning and 'not $500 million from each account' in meaning and 'does not establish a $500 million reduction in the overall account totals' in meaning and 'does not establish a cut to overall account totals' in action['compact_description'],'8067allocation directive became overall-account cut')
    require(all(x in meaning for x in ['$60 million','$127 million','$40 million','$100 million','$173 million','not a second additional $100 million']) and all(x in target['text'] for x in ['$500,000,000','$60,000,000','$127,000,000','$40,000,000','$100,000,000','$173,000,000']),'8067complete allocation amounts or single upper-tier amount lost')
    require("their respective U.S.-Israeli co-production agreements and each nation's laws, regulations and procedures" in meaning and 'Iron Dome procurement subject to the named procurement agreement' in meaning,'8067respective agreement/law conditions lost')
    require('UNACCEPTED candidate proposal' in meaning and 'unaccepted proposal' in action['compact_description'],'8067candidate membership became accepted eligibility')

def validate_atvm_administration_boundaries(action,target):
    meaning=action['meaning'];require('administrative expenses' in target['text'] and '$13,000,000' in target['text'] and 'SEC. 512. $0.' in target['text'],'ATVM exact administrative/SRA target differs')
    require('$13 million is administrative funding, not loan principal or credit subsidy' in meaning and 'administration appropriation to zero' in action['compact_description'],'ATVM administrative reduction became loan-principal cut')
    require('does not repeal the loan program or cancel existing loans' in meaning and 'would not repeal the loan program or cancel existing loans' in action['compact_description'],'ATVM administrative reduction became program repeal')
    require('does not transfer $13 million to a different grant program' in meaning and 'establish a $13 million reduction in actual outlays' in meaning and 'UNACCEPTED candidate proposal' in meaning,'ATVM SRA/actual-outlay or candidate boundary lost')

def validate_northern_border_appropriation_boundaries(action,target):
    meaning=action['meaning'];require('$33,319,727' in target['text'] and 'notwithstanding section 15751(b)' in target['text'],'Northern Border exact account/administrative override differs')
    require('leaving $20 million' in meaning and '$20 million' in action['compact_description'] and '$13,319,727' in meaning,'Northern Border reduction/remainder/SRA amounts differ')
    require('administrative expenses notwithstanding section 15751(b) remains unchanged' in meaning and 'does not reinstate' in meaning and 'Administrative spending permission remains' in action['compact_description'],'Northern Border administrative exception lost')
    require('40 percent of GRANT AMOUNTS' in meaning and 'not 40 percent of this entire appropriation' in meaning and 'not transportation alone' in meaning and 'not a project-specific allocation' in meaning,'Northern Border grant share became account/project allocation')
    require('UNACCEPTED candidate proposal' in meaning and 'membership remains unaccepted' in action['compact_description'],'Northern Border candidate membership became accepted')

def validate_retained_numeric_conflict(record,sources,receipt):
    require(record['disposition']=='source_unresolved' and record['authoritative_source_conflict'] and record['exact_action_binding_unresolved'] and not record['required_evidence_unavailable'] and not record['substantive_review_performed'],'retained237numeric conflict cleared or recast as missing/denied evidence')
    require('$1,114,784,219.49' in sources['govinfo:hrpt119-232-amend33-conflict']['text'] and '$1,114,734,219.49' in sources['congressional-record:2025-09-04-amend33']['text'],'retained237conflicting primary amounts silently repaired')
    require(receipt['selected_operator_or_number'] is None and not receipt['meeting_image_formal_correction_established'] and not receipt['meeting_transcription_reacquired'] and receipt['preimage_sha256']==digest(receipt['preimage']),'retained237meeting transcription became selected/corrected authority')

def validate_vehicle_repeal_boundaries(action,target):
    meaning=action['meaning'];require(all(x in target['text'] for x in ['October 1, 2035','advanced-biofuel-powered vehicle','hydrogen-powered vehicle','may not delegate the waiver authority']),'vehicle repeal complete multi-technology/time/waiver target differs')
    require('Before October 1, 2035' in meaning and 'Beginning October 1, 2035' in meaning and 'not an immediate electric-only requirement for all military vehicles' in meaning and 'advanced-biofuel-powered vehicles, or hydrogen-powered vehicles' in meaning and 'may not delegate that waiver authority' in meaning,'vehicle repeal lost time/technology/waiver qualifications')
    require('does not create a new ban on electric or hybrid procurement' in meaning and 'would not ban electric or hybrid purchases' in action['compact_description'],'vehicle preference repeal became EV procurement ban')
    require('other thirteen listed considerations are not repealed' in meaning and 'UNACCEPTED candidate proposal' in meaning,'vehicle repeal became all-energy-planning repeal or accepted membership')

def validate_mechanism_summary(accounting,core):
    require(accounting['mechanism_types']==sorted({a['legislative_stage'] for a in core['actions']}),'accounting mechanism summary omits or invents an authored action stage')

def validate_cell_cultured_funding_boundaries(action,report):
    meaning=action['meaning'];require('funds authorized to be appropriated by this Act or otherwise made available for fiscal year 2026 for the Department of Defense' in report['text'] and 'research, development, procurement, or promotion of cell cultured meat' in report['text'],'cell-cultured funding/activities primary clause differs')
    require('The first funding description is Act-authorized funds, not merely funds appropriated by this Act' in meaning and 'funds authorized by the Act or specified other fiscal year 2026 Defense funds' in action['compact_description'],'cell-cultured authorization funding collapsed to actual Act appropriations')
    require('research, development, procurement and promotion' in meaning and 'research, development, procurement and promotion' in action['compact_description'] and 'All four activities are part of this one choice' in meaning,'cell-cultured whole activity scope reduced to a selected component')
    require('not a general consumer product ban' in meaning and 'not a general consumer product ban' in action['compact_description'] and 'private funds outside the described funding restriction' in meaning and 'UNACCEPTED candidate proposal' in meaning,'cell-cultured restricted funding became consumer ban or accepted membership')
def validate_north_dakota_exception_scope(record,source):
    text=' '.join(source['text'].split());rationale=record['rationale']
    require('leasing in areas with low development potential may be allowed to prevent drainage of federal minerals' in text and 'categories are revised based on new data or information' in text,'North Dakota retained exception source differs')
    require('The stated drainage/new-data exceptions apply only to low-development-potential leasing; they are not stated exceptions to the drinking-water source-protection closure' in rationale and 'low-potential/drinking-water leasing restrictions have stated drainage/new-data exceptions' not in rationale,'North Dakota exceptions improperly cover drinking-water closure')
    require(record['disposition']=='pending_interpretation' and record['episode_candidate_id'] is None,'North Dakota qualification became membership decision')

def validate_refinery_report_boundaries(action,bill,clerk,compiled,readable):
    require('Not later than 90 days after the date of enactment of this section, the Secretary of Energy shall direct the National Petroleum Council to' in bill['text'],'refinery report primary directive differs')
    require('The 90-day deadline is for the Secretary to direct the Council, not an express 90-day deadline for completing the report' in action['meaning'] and 'Within90days, the Secretary would direct' in action['compact_description'],'refinery direction deadline became report completion deadline')
    require('does not itself permit, fund, construct or require expansion' in action['meaning'] and "not this platform's findings that any policy caused decline" in action['meaning'] and 'UNACCEPTED candidate proposal' in action['meaning'],'refinery report became expansion/causation or accepted membership')
    require('Secretary of Energy and Congress' in action['meaning'] and 'make that report publicly available' in action['meaning'] and all(x in action['meaning'] for x in ['capacity, expansion opportunities and risks','liquid fuels and feedstocks','Federal or State executive actions']),'refinery report whole topics/recipients/public availability omitted')
    require(clerk['member_records']['M001184']['official_label']=='Not Voting' and clerk['member_records']['F000477']['official_label']=='Nay','refinery report own Clerk observations differ')
    member=next(m for m in readable['members'] if m['member_id']=='M001184');require(all('house:119:1:303' not in f['action_ids'] for f in member['findings']),'refinery Not Voting became directional finding')
    member=next(m for m in compiled['members'] if m['member_id']=='M001184');require(member['coverage']['not_voting_actions']==6,'refinery new Not Voting coverage omitted')

def validate_hr144_boundary(capture,universe,membership,receipt):
    ss={s['source_id']:s for s in capture['sources']};source=ss['govinfo:16usc831h-a-and-reporting-note-2024-infra15'];baseline=receipt['complete_baseline_subsection'];require(source['text']==baseline+'\n\n'+receipt['termination_note'],'complete TVA baseline/qualifying note differs');require(all(phrase in baseline for phrase in ['a financial statement','complete report as to the business','cost of power at each power station','$1,500 a year']),'material TVA financial/power-station reporting span lost');lo=baseline.index('a financial statement');hi=baseline.index('$1,500 a year',lo)+len('$1,500 a year');require(receipt['exact_displaced_span']==baseline[lo:hi],'exact displaced TVA span differs');require(receipt['replacement_span'] in ss['govinfo:hr144eh']['text'] and receipt['mechanical_body_after_span_replacement']==baseline[:lo]+receipt['replacement_span']+baseline[hi:],'TVA literal replacement witness differs')
